<?php
require_once "api/app/controller/AuthController.php";
require_once "api/app/controller/GroupController.php";
$auth=new AuthController(); $auth->checkAuth(); $groupController=new GroupController();
$groupId=(int)($_GET['group_id']??0); if($groupId<=0 || !is_group_member($groupId,(int)$_SESSION['unique_id'])){header('Location: groups.php');exit;}
$group=$groupController->getGroup($groupId); if(!$group){header('Location: groups.php');exit;} $memberCount=$groupController->memberCount($groupId); $me=(int)$_SESSION['unique_id']; $myGroupRole=$groupController->membershipRole($groupId,$me); $groupMembers=$groupController->members($groupId)->fetch_all(MYSQLI_ASSOC); $groupCandidates=$myGroupRole==='admin'?$groupController->candidates($groupId):[];
include_once "part/header.php";
?>
<body><div class="app-layout"><?php include "part/sidebar.php"; ?><main class="app-main chat-main">
<?php if(!empty($_SESSION['flash_success'])): ?><div class="notice success"><?php echo e($_SESSION['flash_success']); unset($_SESSION['flash_success']); ?></div><?php endif; ?>
<?php if(!empty($_SESSION['flash_error'])): ?><div class="notice error"><?php echo e($_SESSION['flash_error']); unset($_SESSION['flash_error']); ?></div><?php endif; ?>
<section class="chat-window panel"><header class="chat-header"><a href="groups.php" class="icon-btn"><i class="fas fa-arrow-left"></i></a><img class="avatar" src="assets/img/group-avatar.svg" alt=""><div><h2><?php echo e($group['name']); ?></h2><span class="status-pill online"><?php echo (int)$memberCount; ?> <?php echo e(t('member_count')); ?></span></div></header><div class="chat-box"></div><form action="#" class="group-typing-area composer" enctype="multipart/form-data"><?php echo csrf_input(); ?><input type="hidden" name="group_id" class="group_id" value="<?php echo (int)$group['id']; ?>"><label class="composer-attach" title="<?php echo e(t('attach_file')); ?>"><i class="fas fa-paperclip"></i><input type="file" name="attachment" class="attachment-input"></label><span class="selected-file-name"></span><input type="text" name="message" class="input-field" maxlength="5000" placeholder="<?php echo e(t('message_placeholder')); ?>" autocomplete="off"><button type="submit" aria-label="<?php echo e(t('send')); ?>"><i class="fas fa-paper-plane"></i></button></form></section>
<section class="panel"><div class="section-heading"><div><h2><?php echo e(t('group_management')); ?></h2><p class="subtle"><?php echo e($myGroupRole==='admin'?t('group_admin_help'):t('group_member_help')); ?></p></div></div>
<?php if($myGroupRole==='admin'): ?><form class="inline-admin-form" method="post" action="api/group-action.php"><?php echo csrf_input(); ?><input type="hidden" name="group_id" value="<?php echo (int)$groupId; ?>"><input type="hidden" name="action" value="rename"><label class="field"><span><?php echo e(t('group_name')); ?></span><input name="name" maxlength="160" value="<?php echo e($group['name']); ?>" required></label><button class="btn ghost" type="submit"><?php echo e(t('save')); ?></button></form><?php endif; ?>
<div class="admin-list"><?php foreach($groupMembers as $m): ?><article class="admin-list-row"><img class="avatar tiny" src="<?php echo e(avatar_src($m['img'])); ?>" alt=""><div><strong><?php echo e(display_name($m)); ?></strong><span><?php echo e($m['role']==='admin'?t('group_admin'):t('group_member')); ?> · <?php echo e(role_label($m['user_role'])); ?></span></div><?php if($myGroupRole==='admin' && (int)$m['user_unique_id']!==$me): ?><form method="post" action="api/group-action.php" class="inline-actions"><?php echo csrf_input(); ?><input type="hidden" name="group_id" value="<?php echo (int)$groupId; ?>"><input type="hidden" name="user_id" value="<?php echo (int)$m['user_unique_id']; ?>"><button class="btn ghost small-btn" name="action" value="toggle_admin" type="submit"><?php echo e($m['role']==='admin'?t('make_member'):t('make_admin')); ?></button><button class="icon-btn danger-icon" name="action" value="remove_member" type="submit" title="<?php echo e(t('remove')); ?>"><i class="fas fa-user-minus"></i></button></form><?php endif; ?></article><?php endforeach; ?></div>
<?php if($myGroupRole==='admin' && $groupCandidates): ?><form class="inline-admin-form" method="post" action="api/group-action.php"><?php echo csrf_input(); ?><input type="hidden" name="group_id" value="<?php echo (int)$groupId; ?>"><input type="hidden" name="action" value="add_member"><label class="field"><span><?php echo e(t('add_member')); ?></span><select name="user_id" required><option value=""><?php echo e(t('choose_option')); ?></option><?php foreach($groupCandidates as $p): ?><option value="<?php echo (int)$p['unique_id']; ?>"><?php echo e(display_name($p)); ?></option><?php endforeach; ?></select></label><button class="btn primary" type="submit"><i class="fas fa-user-plus"></i><?php echo e(t('add')); ?></button></form><?php endif; ?>
<div class="dialog-actions"><form method="post" action="api/group-action.php"><?php echo csrf_input(); ?><input type="hidden" name="group_id" value="<?php echo (int)$groupId; ?>"><button class="btn ghost" name="action" value="leave" type="submit"><?php echo e(t('leave_group')); ?></button></form><?php if($myGroupRole==='admin'): ?><form method="post" action="api/group-action.php" onsubmit="return confirm('<?php echo e(t('delete_group_confirm')); ?>')"><?php echo csrf_input(); ?><input type="hidden" name="group_id" value="<?php echo (int)$groupId; ?>"><button class="btn danger" name="action" value="delete_group" type="submit"><?php echo e(t('delete_group')); ?></button></form><?php endif; ?></div>
